rs` on(`active_wallet_orders`.`employee_id` = `u`.`id`)) WHERE `u`.`role` = 'Employee' AND `u`.`deleted_at` is null GROUP BY `u`.`id`, `u`.`name`, `u`.`role`, `active_wallet_orders`.`credited_orders` ;

